"""Euskal Herria outline (Euskadi, Nafarroa and Iparralde) used to decide what the app shows.

Simplified from OpenStreetMap relation 11107464 with tools/make_region.py (Douglas-Peucker, about 200 m of
tolerance, specks under ~1 km2 dropped). Rings are [lon, lat] pairs; the file is regenerated by that tool.
A stop is "inside" when it falls in any ring; the border can be off by a couple of hundred metres.
"""


def _bounds(rings):
    xs = [p[0] for r in rings for p in r]
    ys = [p[1] for r in rings for p in r]
    return min(xs), min(ys), max(xs), max(ys)


def _ring_contains(ring, x, y):
    inside = False
    j = len(ring) - 1
    for i in range(len(ring)):
        xi, yi = ring[i]
        xj, yj = ring[j]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / (yj - yi) + xi:
            inside = not inside
        j = i
    return inside


def contains(lat, lon):
    """True when the point lies inside Euskal Herria."""
    if lat is None or lon is None:
        return False
    x0, y0, x1, y1 = BOUNDS
    if not (x0 <= lon <= x1 and y0 <= lat <= y1):
        return False
    return any(_ring_contains(r, lon, lat) for r in RINGS)


